// tb_dynamic_scheduler_correctness.sv
//
// Phase 15: correctness check for all four dynamic-scheduling demo
// programs (sim/programs/scheduler/{dynamic_scheduler,always_cpu,
// always_accel,oracle}_demo.s, generated by
// scheduler/runtime/gen_dynamic_scheduler_demo.py). Each program runs
// the SAME fixed 6-workload stream (vecadd N=1,2,4; dot N=1,4; matmul
// N=2) and writes every block's real result to the SAME unified RAM
// location regardless of which engine actually produced it (see that
// generator's header comment) -- so all four programs are checked
// against the exact same expected-value table below.
//
// Expected values computed in Python, not by hand:
//
//   python3 -c "
//   def vecadd(n): return [2*i+3 for i in range(n)]
//   def dot(n): return sum((i+1)*(i+2) for i in range(n))
//   def matmul(n):
//       A=[[i+j+1 for j in range(n)] for i in range(n)]
//       B=[[i+j+2 for j in range(n)] for i in range(n)]
//       return [sum(A[i][k]*B[k][j] for k in range(n))
//               for i in range(n) for j in range(n)]
//   print(vecadd(1), vecadd(2), vecadd(4))
//   print(dot(1), dot(4))
//   print(matmul(2))
//   "
//
// This testbench checks CORRECTNESS only, at a fixed generous cycle
// count -- see scheduler/runtime/run_dynamic_scheduler_demo.py for
// the actual sentinel-timed performance comparison between the four
// programs (docs/dynamic_scheduling.md).

`timescale 1ns/1ps

module tb_dynamic_scheduler_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  task automatic check_sentinel(string name, logic [31:0] gpio_out);
    check({name, " sentinel"}, gpio_out, 32'hDEADBEEF);
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  logic [31:0] dyn_gpio, cpu_gpio, accel_gpio, oracle_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/dynamic_scheduler_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_dyn (`SOC_PORTS(dyn_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/always_cpu_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu (`SOC_PORTS(cpu_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/always_accel_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_accel (`SOC_PORTS(accel_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/oracle_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_oracle (`SOC_PORTS(oracle_gpio));

  localparam int MAX_CYCLES = 40000; // always_cpu_demo (matmul N=2 on CPU,
                                      // costliest block) needs the most; kept
                                      // generous rather than tuned tight.

  initial begin
    $display("=== Phase 15 dynamic-scheduling demo correctness check ===");

    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;

    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    check_sentinel("dynamic_scheduler_demo", dyn_gpio);
    check_sentinel("always_cpu_demo", cpu_gpio);
    check_sentinel("always_accel_demo", accel_gpio);
    check_sentinel("oracle_demo", oracle_gpio);

    // block0: vecadd N=1 -> [3], outbase 0x3000 -> mem word 0xC00
    $display("");
    $display("--- block0: vecadd N=1 ---");
    check("dyn    out[0]", dut_dyn.ram_inst.mem[16'h0C00+0], 32'd3);
    check("cpu    out[0]", dut_cpu.ram_inst.mem[16'h0C00+0], 32'd3);
    check("accel  out[0]", dut_accel.ram_inst.mem[16'h0C00+0], 32'd3);
    check("oracle out[0]", dut_oracle.ram_inst.mem[16'h0C00+0], 32'd3);

    // block1: vecadd N=2 -> [3,5], outbase 0x3080 -> mem word 0xC20
    $display("");
    $display("--- block1: vecadd N=2 ---");
    check("dyn    out[0]", dut_dyn.ram_inst.mem[16'h0C20+0], 32'd3);
    check("dyn    out[1]", dut_dyn.ram_inst.mem[16'h0C20+1], 32'd5);
    check("cpu    out[0]", dut_cpu.ram_inst.mem[16'h0C20+0], 32'd3);
    check("cpu    out[1]", dut_cpu.ram_inst.mem[16'h0C20+1], 32'd5);
    check("accel  out[0]", dut_accel.ram_inst.mem[16'h0C20+0], 32'd3);
    check("accel  out[1]", dut_accel.ram_inst.mem[16'h0C20+1], 32'd5);
    check("oracle out[0]", dut_oracle.ram_inst.mem[16'h0C20+0], 32'd3);
    check("oracle out[1]", dut_oracle.ram_inst.mem[16'h0C20+1], 32'd5);

    // block2: vecadd N=4 -> [3,5,7,9], outbase 0x3100 -> mem word 0xC40
    $display("");
    $display("--- block2: vecadd N=4 ---");
    check("dyn    out[0]", dut_dyn.ram_inst.mem[16'h0C40+0], 32'd3);
    check("dyn    out[3]", dut_dyn.ram_inst.mem[16'h0C40+3], 32'd9);
    check("cpu    out[0]", dut_cpu.ram_inst.mem[16'h0C40+0], 32'd3);
    check("cpu    out[3]", dut_cpu.ram_inst.mem[16'h0C40+3], 32'd9);
    check("accel  out[0]", dut_accel.ram_inst.mem[16'h0C40+0], 32'd3);
    check("accel  out[3]", dut_accel.ram_inst.mem[16'h0C40+3], 32'd9);
    check("oracle out[0]", dut_oracle.ram_inst.mem[16'h0C40+0], 32'd3);
    check("oracle out[3]", dut_oracle.ram_inst.mem[16'h0C40+3], 32'd9);

    // block3: dot N=1 -> 2, outbase 0x3180 -> mem word 0xC60
    $display("");
    $display("--- block3: dot N=1 ---");
    check("dyn    result", dut_dyn.ram_inst.mem[16'h0C60+0], 32'd2);
    check("cpu    result", dut_cpu.ram_inst.mem[16'h0C60+0], 32'd2);
    check("accel  result", dut_accel.ram_inst.mem[16'h0C60+0], 32'd2);
    check("oracle result", dut_oracle.ram_inst.mem[16'h0C60+0], 32'd2);

    // block4: dot N=4 -> 40, outbase 0x3200 -> mem word 0xC80
    $display("");
    $display("--- block4: dot N=4 ---");
    check("dyn    result", dut_dyn.ram_inst.mem[16'h0C80+0], 32'd40);
    check("cpu    result", dut_cpu.ram_inst.mem[16'h0C80+0], 32'd40);
    check("accel  result", dut_accel.ram_inst.mem[16'h0C80+0], 32'd40);
    check("oracle result", dut_oracle.ram_inst.mem[16'h0C80+0], 32'd40);

    // block5: matmul N=2 -> [8,11,13,18], outbase 0x3280 -> mem word 0xCA0
    $display("");
    $display("--- block5: matmul N=2 ---");
    check("dyn    out[0]", dut_dyn.ram_inst.mem[16'h0CA0+0], 32'd8);
    check("dyn    out[3]", dut_dyn.ram_inst.mem[16'h0CA0+3], 32'd18);
    check("cpu    out[0]", dut_cpu.ram_inst.mem[16'h0CA0+0], 32'd8);
    check("cpu    out[3]", dut_cpu.ram_inst.mem[16'h0CA0+3], 32'd18);
    check("accel  out[0]", dut_accel.ram_inst.mem[16'h0CA0+0], 32'd8);
    check("accel  out[3]", dut_accel.ram_inst.mem[16'h0CA0+3], 32'd18);
    check("oracle out[0]", dut_oracle.ram_inst.mem[16'h0CA0+0], 32'd8);
    check("oracle out[3]", dut_oracle.ram_inst.mem[16'h0CA0+3], 32'd18);

    $display("");
    if (errors == 0) begin
      $display("RESULT: ALL CHECKS PASSED");
    end else begin
      $display("RESULT: %0d CHECK(S) FAILED", errors);
    end
    $finish;
  end

endmodule
